import sys

def find_sequence(n):
    if n == 1:
        return "1337"

    # Binary search to find the minimum length of the sequence
    low, high = 4, 10**5
    while low < high:
        mid = (low + high) // 2
        # Calculate the number of subsequences in a sequence of length mid
        count = (mid - 3) * (mid - 2) * (mid - 1) // 6
        if count < n:
            low = mid + 1
        else:
            high = mid

    # Construct the sequence
    sequence = []
    remaining = n
    for i in range(low - 3):
        if remaining > 0:
            sequence.append('1')
            remaining -= (low - 3 - i) * (low - 2 - i) * (low - 1 - i) // 6
        if remaining > 0:
            sequence.append('3')
            remaining -= (low - 2 - i) * (low - 1 - i) // 2
        if remaining > 0:
            sequence.append('3')
            remaining -= (low - 1 - i)
        if remaining > 0:
            sequence.append('7')
            remaining -= 1

    # Append additional '1337' to reach the exact count
    while remaining > 0:
        sequence.extend('1337')
        remaining -= 1

    return ''.join(sequence)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    results = []
    index = 1
    for _ in range(t):
        n = int(data[index])
        index += 1
        results.append(find_sequence(n))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
